'Wallet_Payment_Method_Missing' => 'Njia ya malipo ya Wallet haipo',
'Wallet_Payment_Method_Missing_Help' => 'Hakuna njia ya malipo iliyoitwa "Wallet" haswa iliyopatikana. Malipo ya pochi kwenye POS hutambuliwa kwa jina hili, kwa hivyo wateja hawawezi kulipa kwa pochi zao hadi uongeze njia ya malipo iitwayo "Wallet" hapa:',

'Show_Previous_Dues_Line' => 'Onyesha Mstari wa Madeni ya Awali',
'Show_Previous_Dues_Line_Desc' => 'Salio ambalo mteja alikuwa anadaiwa kabla ya mauzo haya. Huchapishwa tu likiwa kubwa kuliko sifuri.',
'Show_Net_Balance_Line' => 'Onyesha Mstari wa Salio Halisi',
'Show_Net_Balance_Line_Desc' => 'Madeni ya awali pamoja na kinachodaiwa bado kwenye mauzo haya. Huchapishwa tu wakati madeni ya awali ni makubwa kuliko sifuri.',

'QZ_Tray_Printer' => 'QZ Tray (printa kwenye kompyuta hii)',
'QZ_Printer_Name_Hint' => 'Jina la printa kama linavyoonekana kwenye kompyuta inayoendesha QZ Tray. Acha wazi ili kutumia printa chaguo-msingi ya kompyuta hiyo. Bofya ⟳ kugundua printa.',
'QZ_Not_Running' => 'QZ Tray haiendeshwi kwenye kompyuta hii. Isakinishe kutoka qz.io na uiache ikiendelea, kisha ruhusu tovuti hii QZ itakapouliza.',
'Detect_Printers' => 'Gundua printa',
'QZ_Download_Cert' => 'Pakua cheti (override.crt)',
'QZ_Setup_Title' => 'Jinsi ya kusanidi uchapishaji wa QZ Tray (mara moja, kwenye kila kompyuta inayochapisha lebo)',
'QZ_Step_Install' => '1. Sakinisha QZ Tray kwenye kompyuta hii — ipakue bure kutoka qz.io, kisha uianze na uiache ikiendelea (inakaa kwenye system tray kwenye Windows au menu bar kwenye macOS).',
'QZ_Step_Connect' => '2. Unganisha printa yako ya lebo kwa USB na uhakikishe imesakinishwa kwenye mfumo wa uendeshaji (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
'QZ_Step_Detect' => '3. Bofya kitufe cha ⟳ kando ya "Jina la printa" hapo juu ili kugundua printa za kompyuta hii, kisha chagua printa yako ya lebo. Acha sehemu wazi ili kutumia printa chaguo-msingi ya kompyuta.',
'QZ_Step_Cert' => '4. Kwa uchapishaji bila dirisha la ruhusa, pakua cheti hapa chini na ukinakili kwenye folda ya usakinishaji ya QZ Tray, ukikipa jina override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Kisha funga QZ Tray na uianze tena.',
'QZ_Step_Test' => '5. Bofya "Chapisha lebo ya majaribio" hapa chini. QZ Tray ikiomba ruhusa, bofya Allow — cheti kikiwa kimesakinishwa haitauliza tena.',
'QZ_Step_Save' => '6. Bofya Submit kuhifadhi mipangilio hii. Lebo kutoka ukurasa wa Chapisha Barcode sasa zitachapishwa moja kwa moja kwenye printa hii, bila dirisha la uchapishaji la kivinjari.',
'QZ_Setup_Note' => 'QZ Tray huendeshwa kwenye kompyuta unayovinjari nayo, kwa hivyo hii hufanya kazi hata Stocky ikiwa kwenye seva ya mbali. Kila kompyuta inayochapisha lebo inahitaji QZ Tray isakinishwe.',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'Washa programu inayoweza kusakinishwa',
'PWA_Enabled_Help' => 'Huruhusu vivinjari kupendekeza kusakinisha programu hii kwenye simu, tableti na kompyuta, na huhifadhi kurasa za nje ya mtandao kwenye kache. Kuizima huondoa pendekezo la usakinishaji kila mahali na kufuta kache katika ziara inayofuata.',
