'PWA_Short_Name' => 'Jina fupi',
'PWA_Short_Name_Help' => 'Huonyeshwa chini ya aikoni kwenye skrini za nyumbani, ambako majina marefu hukatwa. Acha wazi ili kutumia sehemu ya jina la programu kabla ya "|".',
'PWA_Description' => 'Maelezo',
