'PWA_Start_Url' => 'Ukurasa wa kuanzia',
'PWA_Start_Url_Help' => 'Ukurasa ambao programu iliyosakinishwa hufunguka nao, kama njia inayoanza na "/". Tumia /next/pos kufungua moja kwa moja POS.',
'PWA_Display_Mode' => 'Hali ya kuonyesha',
