'Label_Render_Mode' => 'Uchoraji wa lebo',
'Label_Render_Mode_Hint' => 'Jinsi lebo inavyochorwa. Fonti za printa ndiyo haraka zaidi na hutoa barcode iliyo wazi zaidi, lakini huchapisha herufi za Kilatini za msingi tu kwa fonti ya printa yenyewe. Picha ya hakikisho huzalisha muundo wako wa lebo kama ulivyo — fonti uliyochagua, lugha yoyote — kama programu maalum za lebo zinavyofanya.',
'Render_Native' => 'Fonti za printa (haraka zaidi)',
'Render_Raster' => 'Picha ya hakikisho (muundo kamili)',
'Label_Width_Mm' => 'Upana wa lebo (mm)',
'Label_Height_Mm' => 'Urefu wa lebo (mm)',
'Label_Size_Hint' => 'Ukubwa halisi wa stika moja kwenye roli. Lazima ulingane kabisa na lebo zilizowekwa — ukubwa usio sahihi hufanya printa itafute pengo mahali pasipo sahihi, hivyo kila lebo huchapishwa ikiwa imesogea zaidi.',
'Calibrate_Labels' => 'Sawazisha lebo',
'Calibrate_Labels_Hint' => 'Printa hutoa lebo chache kupima stika na pengo. Fanya mara moja baada ya kuweka roli mpya, au nafasi za uchapishaji zinapohama.',
'Calibration_Sent' => 'Usawazishaji umeanza — printa itatoa lebo chache tupu ili kuzipima. Itakaposimama, fanya uchapishaji wa majaribio.',
'Label_Printer_Dpi' => 'Ubora wa kichwa cha printa',
'Label_Printer_Dpi_Hint' => 'Printa nyingi za lebo ni 203 dpi. Huna uhakika? Tumia kitufe cha "Tafuta ubora" hapa chini — huchapisha jibu.',
'Find_Resolution' => 'Tafuta ubora',
'Find_Resolution_Hint' => 'Huchapisha lebo mbili zilizoandikwa 203 na 300. Iliyo sahihi huonyesha mstatili kamili kwenye stika na ukingo mdogo ulio sawa pande zote nne; isiyo sahihi hukosa mipaka au huvuka hadi stika inayofuata.',
'Dpi_Test_Sent' => 'Lebo mbili zilizoandikwa 203 na 300 zinachapishwa. Iliyo sahihi huonyesha mstatili kamili na ukingo mdogo ulio sawa pande zote nne — weka "Ubora wa kichwa cha printa" kwenye namba hiyo na uhifadhi.',
'Label_Offset_X' => 'Msogeo wa mlalo (mm)',
'Label_Offset_X_Hint' => 'Husogeza uchapishaji kando kwenye stika. Tumia wakati maandishi yamekatwa upande mmoja — mfano 2.5 wakati stika nyeupe iko katikati ya karatasi pana zaidi. Rekebisha kwa hatua za 0.5.',
'Label_Offset_Y' => 'Msogeo wa wima (mm)',
'Label_Offset_Y_Hint' => 'Husogeza uchapishaji kando ya lebo. Ongeza wakati sehemu ya juu ya muundo imekatwa au haipo; punguza inapoanza chini sana.',
'Feed_To_Tear' => 'Sukuma hadi ukingo wa kuchana',
