/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'Mwongozo wa oda',
'Ord_Guide_Intro' => 'Jinsi oda iliyowekwa kwenye duka lako la mtandaoni inavyoingia kwenye hisa na hesabu zako, na mahali pesa zinaporekodiwa kwa hakika.',
'Ord_Guide_Lifecycle_Title' => 'Hali ya oda',
'Ord_Guide_Lifecycle_Pending' => 'Oda mpya inayosubiri ukaguzi wako. Oda inayosubiri pekee inaweza kuthibitishwa au kughairiwa.',
'Ord_Guide_Lifecycle_Confirmed' => 'Umekubali oda. Stocky huunda Mauzo katika ghala ulilochagua na kupunguza hisa — mauzo hayo ndiyo rekodi ambayo ripoti zako za hisa, malipo na faida husoma.',
'Ord_Guide_Lifecycle_Shipped' => 'Umetuma oda. Utekelezaji tu: hisa ilikwisha punguzwa ulipothibitisha.',
'Ord_Guide_Lifecycle_Delivered' => 'Mteja amepokea oda. Hili ndilo linaloanzisha kipindi cha kurudisha.',
'Ord_Guide_Lifecycle_Cancelled' => 'Oda iliachwa kabla ya uthibitisho, kwa hivyo hakuna mauzo yaliyoundwa na hakuna hisa iliyopunguzwa.',
'Ord_Guide_PaymentStatus_Tip' => 'Huwekwa wakati wa malipo na haiwezi kuhaririwa hapa. Bofya kuona jinsi ya kurekodi malipo.',
'Ord_Guide_Payment_Title' => 'Hali ya malipo',
'Ord_Guide_Payment_Intro' => 'Safu hii hurekodi jinsi mteja alivyochagua kulipa wakati wa malipo. Huwekwa na duka na haiwezi kuhaririwa kutoka ukurasa huu — pesa zenyewe hufuatiliwa kwenye mauzo ambayo kuthibitisha oda huunda.',
'Ord_Guide_Payment_Paid' => 'Mteja tayari alilipa mtandaoni kupitia lango la malipo. Kuthibitisha oda huunda mauzo kama Paid na kurekodi malipo kwa ajili yako — hakuna kingine cha kufanya.',
'Ord_Guide_Payment_Pending' => 'Malipo wakati wa kufikishwa, uhamisho wa benki au njia nyingine ya kulipa baadaye. Kuthibitisha oda huunda mauzo kama Unpaid, kwa hivyo unarekodi pesa mwenyewe unapozipokea — angalia hatua zilizo hapa chini.',
'Ord_Guide_Payment_Failed' => 'Lango lilikataa malipo au mteja aliyaacha. Oda hughairiwa kiotomatiki.',
'Ord_Guide_MarkPaid_Title' => 'Kubadilisha malipo kutoka pending kuwa paid',
'Ord_Guide_MarkPaid_Step1' => 'Thibitisha oda hapa kwanza — kuthibitisha ndiko kunakounda mauzo.',
'Ord_Guide_MarkPaid_Step2' => 'Fungua Sales > All Sales na utafute mauzo hayo (mteja yule yule, na ukurasa wa maelezo huonyesha oda ya mtandaoni iliyotoka).',
'Ord_Guide_MarkPaid_Step3' => 'Fungua menyu ya vitendo vya mstari na uchague Create Payment.',
'Ord_Guide_MarkPaid_Step4' => 'Weka kiasi, njia ya malipo na tarehe, kisha hifadhi. Mauzo hubadilika kuwa Partial au Paid yenyewe, kulingana na kiasi.',
'Ord_Guide_MarkPaid_Note' => 'Hali ya Malipo inayoonyeshwa hapa huendelea kurekodi chaguo la wakati wa malipo na hubaki kama ilivyo. Mauzo ndiyo rekodi ya uhasibu, na ndiyo inayolisha ripoti zako za malipo na faida. Tumia Show Payments kwenye mauzo kukagua au kuhariri ulichoweka.',
'Ord_Guide_Notes_Title' => 'Vizuri kujua',
'Ord_Guide_Note_Warehouse' => 'Ghala unalochagua unapothibitisha huamua mahali hisa inapochukuliwa. Maghala yasiyoweza kutosheleza oda nzima huwekwa alama Out of Stock katika orodha hiyo.',
'Ord_Guide_Note_Preorder' => 'Bidhaa za oda ya awali huruka ukaguzi wa hisa, kwa hivyo oda inayozijumuisha inaweza kuthibitishwa hata idadi isipokuwepo bado.',
'Ord_Guide_Note_Flagged' => 'Alama ya Flagged inamaanisha oda ilinaswa na ukaguzi wa udanganyifu wakati wa malipo. Elea juu ya alama kuona sababu na ukague oda kabla ya kuithibitisha.',
'Ord_Guide_Note_Cancel' => 'Kughairi kunawezekana tu wakati oda bado inasubiri. Ikishathibitishwa, irudishe kupitia mauzo au kurudishwa na mteja badala yake.',


