// Variants guide drawer (product form).
'Guide' => 'Mwongozo',
'Variants_Guide' => 'Mwongozo wa matoleo',
'VG_Intro' => 'Bidhaa yenye matoleo huuzwa kama matoleo kadhaa. Yaunde kutokana na chaguo (inapendekezwa) au kama orodha rahisi ya majina. Kila toleo lina msimbo, bei, picha na stoku yake.',
'VG_Options_Title' => 'Hali ya chaguo (Rangi, Saizi...)',
'VG_Opt_Step1' => 'Acha swichi iliyo kwenye kichwa cha kadi kwenye "Chaguo".',
'VG_Opt_Step2' => 'Andika jina la chaguo kama Rangi au Saizi, au chagua mojawapo ya mapendekezo.',
'VG_Opt_Step3' => 'Andika thamani (kwa mfano Nyekundu) na ubonyeze Enter. Rudia kwa kila thamani; koma pia hutenganisha thamani. Bofya x kwenye thamani ili kuiondoa.',
'VG_Opt_Step4' => 'Bofya "Ongeza chaguo" kwa chaguo la pili au la tatu (chaguo 3 kwa kiwango cha juu).',
'VG_Opt_Step5' => 'Bofya "Zalisha matoleo". Safu moja huundwa kwa kila mchanganyiko na jina lake hujengwa kiotomatiki, kwa mfano "Red / S".',
'VG_Opt_Step6' => 'Weka gharama na bei kwenye kila safu, au andika thamani kwenye "Tumia kwa zote" na ubofye Gharama au Bei ili kuinakili kwenye kila safu.',
'VG_Opt_Step7' => 'Misimbo huzalishwa kwa ajili yako. Andika yako mwenyewe au bofya ikoni ya kuonyesha upya ili kuzalisha nyingine.',
'VG_Opt_Step8' => 'Si lazima: weka alama kwenye "Sampuli za rangi" kwenye chaguo na uchague rangi kwa kila thamani; duka huionyesha kama kitone cha rangi.',
'VG_Rows_Title' => 'Safu za matoleo',
'VG_Rows_Text' => 'Kila safu ina picha, msimbo, msimbopau, gharama, bei, bei ya jumla na bei ya chini ya kuuza. Unapounda bidhaa unaweza pia kuweka stoku ya kuanzia kwa kila ghala kwa kila toleo. Lebo ya "Haijakamilika" inamaanisha safu inakosa thamani ya chaguo moja.',
'VG_List_Title' => 'Hali ya orodha rahisi',
'VG_List_Text' => 'Andika jina la toleo na ubonyeze Enter (au bofya Ongeza) ili kuongeza safu, kisha jaza msimbo na bei zake. Hii ndiyo tabia ya kawaida na inabaki kupatikana kwa bidhaa zilizopo.',
'VG_Edit_Title' => 'Kuhariri baadaye',
'VG_Edit_1' => 'Ongeza thamani na ubofye "Zalisha matoleo": michanganyiko inayokosekana pekee ndiyo huongezwa. Safu zilizopo huhifadhi misimbo, bei na historia yake.',
'VG_Edit_2' => 'Kuondoa thamani au chaguo huondoa safu zinazoitumia. Safu zilizokwisha hifadhiwa hufutwa unapohifadhi bidhaa, baada ya uthibitisho.',
'VG_Edit_3' => 'Toleo ambalo bado lina stoku haliwezi kuondolewa. Rekebisha au hamisha stoku yake kwanza.',
'VG_Edit_4' => 'Kubadili kwenda "Orodha rahisi" huhifadhi safu na majina yake lakini huondoa ufafanuzi wa chaguo.',
'VG_Store_Title' => 'Kwenye duka la mtandaoni',
'VG_Store_Text' => 'Wateja huchagua thamani moja kwa kila chaguo, kwa mfano Rangi kisha Saizi. Michanganyiko isiyokuwepo huzimwa na zisizo na stoku hukatwa mstari. Toleo lililochaguliwa ndilo huenda kwenye kikapu.',
