'Portal_Quotation_Requests' => 'Maombi ya nukuu ya bei kutoka lango',
'Warehouse_Invoice_Address_Help' => 'Anwani ya mtaa inayochapishwa kwenye ankara zinazotolewa na ghala hili. Acha wazi ili kutumia anwani ya kampuni kutoka mipangilio.',
'Warehouse_Logo_Help' => 'Nembo inayochapishwa kwenye ankara na risiti za POS za ghala hili. Acha wazi ili kutumia nembo ya kampuni.',
