'Upd_Guide_Before_Title' => '1. Kabla ya kusasisha',
'Upd_Guide_Before_Download' => 'Pakua {package} ya programu kutoka kwenye akaunti yako ya CodeCanyon ({path}). Usiifungue — kisasishaji kinahitaji ZIP kama ilivyopakuliwa hasa.',
'Upd_Latest_Full_Zip' => 'kifurushi kamili cha ZIP cha hivi karibuni',
'Upd_Guide_Before_Admin' => 'Hakikisha umeingia kama msimamizi mwenye ruhusa ya {perm}. Hakuna mtu mwingine anayeweza kuona au kuendesha kisasishaji.',
'Upd_Guide_Before_Quiet' => 'Chagua wakati tulivu: wakati wa kusasisha programu huingia kwenye hali ya matengenezo kwa muda mfupi na watumiaji wengine hufungiwa nje.',
'Upd_Guide_Before_No_Manual' => 'Huhitaji {not} kuchukua nakala rudufu kwa mkono, kufungua faili, kuendesha amri, kuhariri faili za usanidi, au kugusa hifadhidata — kisasishaji hufanya yote hayo kiotomatiki. (Bila shaka, nakala rudufu ya ziada kwa mkono haidhuru kamwe.)',
'Upd_Not' => 'kabisa',
'Upd_Guide_Code_Overwritten' => 'Ikiwa umebadilisha msimbo wa programu kwa mkono, mabadiliko yako yataandikwa juu na sasisho. Data yako, faili zilizopakiwa, mipangilio na .env huhifadhiwa daima.',
'Upd_Guide_Running_Title' => '2. Kuendesha sasisho',
'Upd_Guide_Run_Open' => 'Fungua {path} (ukurasa huu) na ubaki kwenye kichupo cha {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: bofya au buruta kifurushi kilichopakuliwa kwenye kisanduku cha kupakia. Faili kubwa hupakiwa kwa vipande vidogo, kwa hivyo hii inafanya kazi pia kwenye hosting ya pamoja yenye mipaka midogo ya upakiaji. Checksum hulinda dhidi ya upakiaji ulioharibika au usiokamilika.',
'Upd_Upload_The_Zip' => 'Pakia ZIP',
'Upd_Guide_Run_Validation' => '{auto} baada ya kupakia (unaweza kuuendesha tena kwa kitufe cha {button}). Mfumo hukagua: uadilifu wa ZIP, muundo na ukamilifu wa kifurushi, uoanifu wa toleo (kushusha toleo kunakataliwa), toleo la PHP na viendelezi vinavyohitajika, ruhusa za faili, nafasi ya diski iliyo wazi, muunganisho wa hifadhidata, usanidi, na kwamba hakuna sasisho jingine linaloendelea.',
'Upd_Validation_Runs_Automatically' => 'Uthibitishaji huendeshwa kiotomatiki',
'Upd_Guide_Run_Review' => 'Kagua paneli ya {panel}. Kitufe cha {button} huonekana tu wakati kila ukaguzi muhimu umefaulu. Ukaguzi ukishindwa, ujumbe hukueleza hasa kile cha kurekebisha.',
'Upd_Guide_Run_Click' => 'Bofya {button} na uthibitishe. Kisha {keep} tu na utazame upau wa maendeleo. Mfumo hutekeleza, kwa mpangilio:',
'Upd_Keep_Page_Open' => 'acha ukurasa huu wazi',
'Upd_Guide_Phase_Backup' => '{label} — nakala kamili ya hifadhidata, ZIP ya kila faili la programu ambalo sasisho linaweza kubadilisha, na nakala ya {env} huundwa na {verified}. Faili zako zilizopakiwa ({images}) na {storage} kamwe haziguswi na sasisho, kwa hivyo hazihifadhiwi kwenye kumbukumbu. Ikiwa nakala rudufu haiwezi kuundwa, sasisho husimama hapa na hakuna kinachobadilishwa.',
'Upd_Verified' => 'kuthibitishwa',
'Upd_Guide_Phase_Prepare' => '{label} — toleo jipya hufunguliwa kwenye eneo la maandalizi na kuthibitishwa tena. Programu inayofanya kazi bado haijaguswa.',
'Upd_Guide_Phase_Maintenance' => '{label} — hali ya matengenezo huwashwa; wageni huona skrini ya kirafiki ya "Tutarudi hivi punde".',
'Upd_Guide_Phase_Files' => '{label} — faili mpya huwekwa karibu papo hapo; faili za zamani huhifadhiwa kando kwa ajili ya kurejesha. Njia zinazolindwa ({env}, {storage}, {images}) kamwe hazibadilishwi.',
'Upd_Guide_Phase_Database' => '{label} — migrations huendeshwa, kisha ruhusa, tafsiri na violezo huonyeshwa upya.',
'Upd_Guide_Phase_Cache' => '{label} — akiba zote hufutwa na kujengwa upya.',
'Upd_Guide_Phase_Verify' => '{label} — ukaguzi wa afya huthibitisha kwamba toleo jipya linawaka, hifadhidata inafanya kazi, migrations zote zimeendeshwa, na usanidi ni halali.',
'Upd_Guide_Phase_Done' => '{label} — hali ya matengenezo huondolewa na faili za muda husafishwa.',
'Upd_Guide_Run_Success' => 'Unapoona {success}, bofya {reload} na uonyeshe upya kivinjari chako kwa nguvu ({keys}) ili rasilimali mpya za paneli ya msimamizi zipakie.',
'Upd_Update_Successful_Short' => 'Sasisho limefanikiwa',
'Upd_Guide_No_Internet' => 'Hakuna muunganisho wa intaneti unaohitajika wakati wa kusasisha — kila kitu kinatoka kwenye ZIP iliyopakiwa. Kupoteza muunganisho au kufunga kivinjari HAKUVURUGI sasisho: seva hukumbuka hasa mahali iliposimama.',
'Upd_Guide_Wrong_Title' => '3. Ikiwa kitu kitaenda vibaya',
'Upd_Guide_Wrong_Rollback' => '{label} — ikiwa chochote kitashindwa baada ya faili kuanza kubadilika (hitilafu ya kufungua, kushindwa kwa migration, ukaguzi wa afya kushindwa, diski kujaa, …), mfumo hurejesha kiotomatiki faili za awali na hifadhidata kutoka kwenye nakala rudufu iliyothibitishwa, huondoa hali ya matengenezo, na huripoti {message}. Unarudi hasa pale ulipoanzia.',
'Upd_Automatic_Rollback' => 'Urejeshaji wa kiotomatiki',
'Upd_Failed_Previous_Restored' => 'Sasisho limeshindwa — toleo la awali limerejeshwa',
'Upd_Guide_Wrong_Interrupted' => '{label} (seva kuwashwa upya, muda kuisha, kivinjari kufungwa, kukatika kwa umeme) — unapofungua ukurasa huu tena, bango jekundu hutoa chaguo mbili salama: {resume} (huendelea kutoka hatua hasa iliposimama) au {rollback} (hurejesha toleo la awali kutoka kwenye nakala rudufu).',
'Upd_Interrupted_Update' => 'Sasisho lililokatizwa',
'Upd_Guide_Wrong_Unreachable' => '{label} — tumia {console} inayojitegemea katika {path}. Inafanya kazi hata wakati tovuti iko kwenye hali ya matengenezo au rasilimali za paneli ya msimamizi zimeharibika, na inatoa vitendo vilevile vya Endelea / Rejesha. Pia kuna kiungo kisichoonekana sana cha "Ufikiaji wa Msimamizi" chini ya skrini ya matengenezo.',
'Upd_Admin_Unreachable' => 'Paneli ya msimamizi haifikiki',
'Upd_Recovery_Console' => 'konsoli ya urejeshaji',
'Upd_Guide_Wrong_Locked_Out' => '{label} — wakati sasisho linaendelea, ukurasa huu huonyesha {link}. Kihifadhi ikiwa unahitaji kurudi ndani (kwa mfano baada ya kipindi chako kuisha); kinakupitisha kwenye skrini ya matengenezo ili uweze kuingia tena.',
'Upd_Locked_Out_Maintenance' => 'Umefungiwa nje na hali ya matengenezo',
'Upd_Bypass_Link' => 'kiungo cha kupita',
'Upd_Guide_Wrong_Concurrent' => '{label} — wataona {message} Sasisho moja tu linaweza kuendeshwa kwa wakati mmoja.',
'Upd_Another_Admin_Updating' => 'Msimamizi mwingine anajaribu kusasisha kwa wakati mmoja',
'Upd_Guide_Backups_Title' => '4. Nakala rudufu na urejeshaji',
'Upd_Guide_Backups_Created' => 'Kila sasisho huunda nakala rudufu {before} ya kugusa chochote: faili zote za programu ambazo sasisho linaweza kubadilisha, nakala ya {env}, na nakala kamili ya hifadhidata. Faili zilizopakiwa na {storage} kamwe hazibadilishwi na sasisho na kwa hivyo si sehemu yake — weka nakala rudufu zako mwenyewe za hizo. Nakala rudufu huhifadhiwa katika {path} na kamwe hazifikiki kutoka kwenye wavuti.',
'Upd_Before' => 'kabla',
'Upd_Guide_Backups_Panel' => 'Paneli ya {panel} kwenye kichupo cha {tab} huziorodhesha pamoja na tarehe, toleo na ukubwa. Kutoka hapo unaweza {restore} nakala rudufu yoyote kamili (faili + hifadhidata — nakala ya usalama ya hifadhidata ya sasa huchukuliwa kwanza) au {delete} za zamani.',
'Upd_Restore_Verb' => 'kurejesha',
'Upd_Delete_Verb' => 'kufuta',
'Upd_Guide_Backups_Retention' => 'Tumia {keep} kuchagua idadi ya nakala rudufu zinazohifadhiwa; za zamani huondolewa kiotomatiki baada ya kila sasisho lililofanikiwa. Nakala rudufu kamili pekee iliyobaki haiwezi kufutwa kamwe — daima unabaki na njia ya kurudi.',
'Upd_Guide_Manual_Title' => '5. Kusasisha kwa mkono (njia mbadala)',
'Upd_Guide_Manual_Text' => 'Ikiwa unapendelea kusasisha kwa mkono, au kipakiaji hakiwezi kutumika kwenye seva yako, fuata maagizo ya hatua kwa hatua kwenye kichupo cha {tab} cha ukurasa huu.',
'Upd_Guide_Clear_Cache_First' => 'Ikiwa kurasa zinaonekana zimeharibika au tupu baada ya sasisho lolote, futa akiba ya kivinjari chako kwanza — karibu kila mara hiyo ndiyo sababu.',
'Upd_Restore_Backup_Confirm' => 'Rejesha nakala hii ya akiba? Faili za sasa na hifadhidata ya sasa zitabadilishwa na nakala ya akiba. Nakala ya usalama ya hifadhidata ya sasa huchukuliwa kwanza. (v{version} — {date})',
'Woo_Guide_Lead' => 'Jinsi duka la WooCommerce linavyobaki likiendana na ERP. Mistari ya cron hapa chini imetengenezwa kwa ajili ya seva hii, hivyo inaweza kunakiliwa moja kwa moja.',
'Woo_Guide_Ways_Note' => 'Tofauti na Shopify, WooCommerce haitumi chochote kwa ERP yenyewe — hakuna kipokezi cha webhook hapa, hivyo kila kinachoingia {in} hufika kwa ratiba. Ni stoku inayotoka {out} pekee inayoweza kwenda papo hapo.',
'Woo_In' => 'ndani',
'Woo_Out' => 'nje',
'Woo_Guide_Both_Ways_Title' => 'Njia zote mbili zinahitaji hili kwanza',
'Woo_Api_Keys' => 'Funguo za API',
'Woo_Guide_Api_Keys_Text' => '{path}, ruhusa {perm}. Nakili consumer key na secret kwenye kichupo cha {settings}, pamoja na URL ya duka — anwani ya tovuti yako bila kufyeka mwishoni, k.m. {example}.',
'Woo_Credentials_Saved' => 'vitambulisho vimehifadhiwa',
'Woo_Not_Configured_Yet' => 'bado haijasanidiwa',
'Woo_Guide_Wp_App_Password_Title' => 'Nenosiri la programu la WordPress (si lazima)',
'Woo_Guide_Wp_App_Password_Text' => 'Hutumika kwa picha za bidhaa pekee. API ya WooCommerce husafirisha bidhaa, stoku, kategoria, chapa, wateja na oda; API ya WordPress ndiyo hutafuta kwenye Maktaba ya Media na kupakia picha ambayo bado haipo.',
'Woo_Guide_Wp_App_Password_Note' => 'Tumia mtumiaji wa WordPress anayeweza kusimamia media, na uunde nenosiri chini ya {path}. Ukiacha sehemu zote mbili wazi kila kitu bado kinasawazishwa — ni kuambatisha picha pekee kunakorukwa.',
'Woo_Guide_Pick_Way_Title' => 'Kisha chagua jinsi inavyobaki ikiendana',
'Woo_Right_Away' => 'Papo hapo',
'Woo_Stock_Live' => 'stoku hai',
'Woo_Stock_Not_Live' => 'stoku si hai',
'Woo_Guide_Realtime_Lead' => 'Mwelekeo mmoja tu: stoku na bidhaa zinazotoka ERP. Oda na marekebisho ya bidhaa yaliyofanywa kwenye WooCommerce bado hufika kwa ratiba — angalia kichupo kingine.',
'Woo_Push_Stock_On_Change' => 'Tuma stoku mara inapobadilika',
'Woo_Setting_People_Miss' => 'Hii ndiyo mipangilio ambayo watu husahau',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Mauzo ya POS {not} WooCommerce yenyewe. Ikiachwa imezimwa, duka hugundua tu kwenye usawazishaji unaofuata wa stoku — saa moja, kwa chaguo-msingi — na katika muda huo linaweza kuuza kipande ulichokwisha kuuza kaunta.',
'Woo_Does_Not' => 'hayafiki',
'Woo_Guide_Tick_Instant' => 'Weka alama {option} kwenye kichupo cha {settings}. Huo ndio usanidi wote — hakuna worker, hakuna cron. Kila mauzo, marejesho, marekebisho, uhamisho na ununuzi uliopokelewa basi hutuma stoku ya bidhaa hizo tu, mara baada ya mauzo kuhifadhiwa, na mauzo ya mistari ishirini hugharimu utumaji mmoja, si ishirini. Kaunta haisubiri kamwe.',
'Woo_Currently' => 'Kwa sasa:',
'Woo_Instant_On_Text' => 'imewashwa — stoku hutumwa inapobadilika',
'Woo_Instant_Off_Text' => 'imezimwa — stoku kwa ratiba pekee',
'Woo_Guide_Instant_Note' => 'Ni bidhaa ambazo tayari zimeunganishwa na WooCommerce pekee zinazotumwa — bidhaa ambayo haijawahi kusawazishwa haina chochote dukani cha kusahihisha. Bidhaa zenye matoleo hupitia bidhaa mzazi, na combo hutumwa upya sehemu yake yoyote inapobadilika. Shughuli za jumla (kufuta bidhaa, kuweka upya ghala) huandika stoku bila kuanzisha tukio, ambayo ni sababu moja ya kuendelea na usawazishaji wa stoku wa kila saa pia.',
'Woo_Push_Products_On_Save' => 'Tuma bidhaa mara zinapohifadhiwa',
'Woo_Guide_Tick_Auto_Products' => 'Weka alama {option} kwenye kichupo cha {settings} na bidhaa iliyoundwa, kuhaririwa au kunakiliwa kwenye Stocky hutumwa WooCommerce mara baada ya kuhifadhiwa — maelezo, bei, matoleo na picha, kisha stoku yake. Bidhaa mpya huundwa dukani mara moja badala ya kusubiri usawazishaji wa bidhaa wa usiku.',
'Woo_On' => 'imewashwa',
'Woo_Off' => 'imezimwa',
'Woo_Guide_Bulk_Imports_Note' => 'Uingizaji wa jumla hautumwi moja moja — endesha usawazishaji wa bidhaa baada ya kuingiza. Sawazisha kategoria na chapa kwanza, ili bidhaa inayotumwa iingie kwenye kategoria sahihi.',
'Woo_Nothing_Else_To_Install' => 'Hakuna kingine cha kusakinisha',
'Woo_Guide_Same_Process' => 'Hakuna queue worker, hakuna ingizo la cron. Utumaji huendeshwa kwenye mchakato uleule uliohudumia mauzo, {after} jibu kurudishwa, hivyo kaunta haisubiri WooCommerce kamwe. Utumaji haupishani: mabadiliko yanayofanywa wakati mmoja unaendelea huusubiri na kwenda mara baadaye.',
'Woo_After' => 'baada ya',
'Woo_Guide_Shop_Stops_Answering' => 'Duka linaloacha kujibu huachwa baada ya sekunde nane, na utumaji husimama kwa dakika tano ili kila mauzo yasilisubiri tena; mabadiliko yaliyoingia katikati hutumwa na utumaji wa kwanza baada ya kusimama, na usawazishaji wa stoku wa kila saa hufidia hata hivyo. Kila kusimama hurekodiwa kwenye kichupo cha Kumbukumbu.',
'Woo_Guide_Artisan_Exception' => 'Isipokuwa moja: mabadiliko ya stoku yaliyofanywa na amri ya artisan hayana jibu la kufuatwa, hivyo huwekwa kwenye foleni {queue} badala yake. Ili hayo nayo yatumwe haraka, endesha foleni hiyo:',
'Woo_Cron_Line_Copied' => 'Mstari wa cron umenakiliwa',
'Woo_Command_Copied' => 'Amri imenakiliwa',
'Woo_Guide_Not_Woo_Queue' => 'Kwa makusudi si foleni ya {queue}: hiyo hubeba makundi ya katalogi yanayochukua saa nyingi, na utumaji wa papo hapo uliowekwa nyuma ya moja usingekuwa wa papo hapo.',
'Woo_On_A_Schedule' => 'Kwa ratiba',
'Woo_Guide_Scheduled_Lead' => 'Kila kitu hukaguliwa upya mara kwa mara, pande zote mbili. Hivi ndivyo oda zinavyofika ERP, jinsi katalogi inavyochapishwa, na kinachorekebisha chochote ambacho njia ya haraka ilikosa. Kila kazi ina ingizo lake la cron, hivyo unaendesha tu unachotaka.',
'Woo_Guide_Sync_Drains_Queue' => '{command} huendesha foleni yake yenyewe wakati inaendeshwa, hivyo mistari hii haihitaji worker tofauti. Kwenye Windows, tumia Task Scheduler na programu {program} na hoja zilezile, ikianzia kwenye {path}.',
'Woo_Or_No_Cron' => 'Au bila cron kabisa',
'Woo_Guide_No_Cron_Text' => 'Kila kichupo hapa husawazisha unapohitaji, na usawazishaji wa mkono huendesha makundi yake wakati ukurasa uko wazi — hivyo duka dogo linaweza kufanya kazi bila ingizo lolote la cron. Unachopoteza ni kila kinachotokea wakati hakuna anayeangalia: oda hufika tu mtu anapobonyeza kitufe.',
'Woo_Commands_Worth_Knowing' => 'Amri zinazofaa kujua',
