'Woo_Guide_Changing_Url_Clears' => 'Kubadilisha URL ya duka au funguo za API hufuta kila uhusiano — bidhaa, kategoria, chapa na wateja vyote husawazishwa upya kwenye duka jipya.',
'Woo_Guide_Keep_Skus' => 'Weka SKU ziwe sawa kati ya Stocky na WooCommerce: hilo ndilo huzuia nakala rudufu na hufanya kuunganisha upya kuwe salama.',
