'Woo_Settings_Auto_Products_Hint' => 'Bidhaa iliyoundwa, kuhaririwa au kunakiliwa kwenye Stocky hutumwa WooCommerce mara baada ya kuhifadhiwa — maelezo, bei, matoleo, picha, kisha stoku yake — badala ya kusubiri usawazishaji wa bidhaa. Uingizaji wa jumla hautumwi; endesha usawazishaji wa bidhaa baada ya kuingiza.',
'Woo_Sync_Tuning' => 'Urekebishaji wa usawazishaji',
'Woo_Sync_Tuning_Intro' => 'Chaguo-msingi zinafaa maduka mengi. Badilisha haya tu ikiwa usawazishaji ni wa polepole au unaisha muda kwenye hosting yako. Kila thamani imewekewa kikomo cha masafa salama, na kufuta sehemu hurejesha chaguo-msingi lake.',
