'Presta_Pull_Orders_Desc' => 'Huingiza oda za duka kama mauzo (kumbukumbu kama {ref}), za karibuni kwanza. Oda zilizokwisha kuingizwa na zilizoghairiwa zinarukwa, hivyo kuvuta mara kwa mara ni salama. PrestaShop haina webhooks — endesha hii baada ya vipindi vyenye shughuli nyingi.',
'Presta_Guide_1' => 'Katika ofisi ya nyuma ya PrestaShop, fungua {menu} na uwashe webservice.',
