'Presta_Guide_4' => 'Vuta bidhaa kwanza ikiwa duka tayari lina katalogi (hulinganisha kwa reference/SKU); tuma ili kuunda bidhaa rahisi zinazokosekana.',
'Presta_Guide_5' => 'Tuma stoku kila idadi zinapobadilika, na vuta oda mara kwa mara — PrestaShop haina webhooks, hivyo oda hufika tu unapovuta.',
'Presta_Identity_Title' => 'Utambulisho wa bidhaa ni reference (SKU)',
'Presta_Identity_Desc' => 'Msimbo wa bidhaa wa Stocky hulinganishwa na reference ya PrestaShop. Weka reference ziwe sawa pande zote mbili; combinations (matoleo) hulinganishwa kwenye oda kwa reference lakini hazitumwi katika toleo hili.',
