'Xero_Push_Invoices_Desc' => 'Huunda ankara moja ya AUTHORISED kwa kila mauzo (namba ya ankara = Kumbukumbu ya mauzo), ikiwa na bidhaa za mauzo pamoja na mistari ya usafirishaji, punguzo na kodi ili jumla ya Xero ilingane na jumla ya mauzo. Mauzo yaliyokwisha kuwa kwenye Xero yanarukwa — ankara hazihaririwi kamwe. Anwani zinazokosekana huundwa papo hapo.',
