'Jumia_Push_Prices_Stock_Title' => 'Tuma bei na stoku kwenda Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Hutuma bei na idadi ya sasa ya kila bidhaa (na toleo) yenye SKU inayolingana na {sku} ya orodha ya Jumia. Masasisho huwasilishwa kama feeds za Seller Center na kutekelezwa bila kusubiri — ID ya feed hurekodiwa kwenye kichupo cha Kumbukumbu, na makataa ya kila kipengee huonekana kwenye skrini ya hali ya feed ya Seller Center.',
'Jumia_Push_Prices_Stock' => 'Tuma bei na stoku',
'Jumia_Pull_Orders_Desc' => 'Huingiza oda za soko kama mauzo (kumbukumbu kama {ref}), zikilinganishwa na bidhaa zako kwa Seller SKU. Oda zilizokwisha kuingizwa na zilizoghairiwa zinarukwa, hivyo kuvuta mara kwa mara ni salama. Malipo huwekwa kama yamelipwa kwa oda zilizowasilishwa pekee (Jumia hutawaliwa na malipo wakati wa kupokea - COD).',
'Jumia_Guide_1' => 'Katika Jumia {sellerCenter}, fungua {menu} na utengeneze ufunguo wa API.',
'Jumia_Guide_2' => 'Weka URL ya API ya nchi yako (k.m. {ng} kwa Nigeria, {ke} kwa Kenya, {eg} kwa Misri), barua pepe ya akaunti yako ya Seller Center, na ufunguo — kisha endesha {test}.',
'Jumia_Guide_3' => 'Hakikisha {sku} ya kila orodha ya Jumia ni sawa na msimbo wa bidhaa wa Stocky — huo ndio utambulisho unaotumika kwa utumaji wa stoku na ulinganishaji wa oda.',
'Jumia_Guide_4' => 'Tuma bei na stoku baada ya mabadiliko ya hesabu ya stoku; vuta oda mara kwa mara (Jumia haina webhooks katika API hii).',
'Jumia_Guide_5' => 'Kuunda orodha mpya kunabaki kwenye Seller Center — Jumia inahitaji sifa maalum za kategoria na ukaguzi wa picha ambao ni lango lao pekee linaloushughulikia vizuri.',
