'Shopify_G_Lead_Store' => 'Kile duka hili linahitaji ili kubaki likiendana. Kila kitu hapa ni mahususi kwa duka hili — njia na ID ni halisi, hivyo amri zinaweza kunakiliwa moja kwa moja kwenye seva.',
'Shopify_G_Lead_Generic' => 'Jinsi duka la Shopify linavyobaki likiendana na ERP. Chagua duka hapo juu kuona hali yake, au isome kama ilivyo — mstari wa cron na URL ya Webhook ni zile zile bila kujali duka unalounganisha.',
'Shopify_G_Ways_Note' => 'Maduka mengi huendesha zote mbili: ya kwanza huweka duka likiwa la kisasa dakika kwa dakika, ya pili hunasa chochote ambacho ya kwanza ilikosa — Webhook ambayo haikuwahi kufika, uhariri uliofanywa moja kwa moja kwenye admin ya Shopify, usiku ambao tovuti ilikuwa chini.',
'Shopify_G_Both_Need' => 'Njia zote mbili zinahitaji hiki kwanza',
'Shopify_G_Credentials' => 'Vitambulisho vya Shopify',
'Shopify_G_Cred_Intro' => 'Tangu Januari 2026 Shopify haiundi tena programu maalum ndani ya admin, hivyo kuna aina mbili za muunganisho:',
'Shopify_G_Cred_DevDash' => '{app} (duka lolote linalounganishwa sasa) — {path}. Toa ruhusa (scopes) za Admin API kwa kile duka hili husawazisha, sakinisha programu kwenye duka, kisha nakili {clientId} na {clientSecret} kutoka ukurasa wa Mipangilio wa programu kwenda {where}. ERP yenyewe huzibadilisha kuwa tokeni ya ufikiaji na kuifanya upya kabla haijaisha muda kila baada ya saa 24. Client secret pia husaini Webhook, hivyo hakuna kingine kinachohitajika. Programu na duka lazima viwe ndani ya shirika moja la Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'Programu ya Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (iliyoundwa kwenye admin kabla ya 2026) — inaendelea kufanya kazi bila mabadiliko kwa {token} yake ({prefix}) na {secret} yake kama siri ya kusaini Webhook. Si thamani sawa na tokeni, na kuzichanganya ndiyo sababu ya kawaida ya Webhook kukataliwa.',
'Shopify_G_Legacy_App' => 'Programu maalum ya zamani',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'imehifadhiwa',
'Shopify_G_Missing_Refused' => 'haipo — uwasilishaji utakataliwa',
'Shopify_G_Where_Data_Desc' => '{path} Ghala la ERP ambalo stoku yake inauzwa na duka hili, na eneo la Shopify ambako stoku hiyo huandikwa. Usawazishaji wa stoku na uingizaji wa oda vyote hukataa kuendeshwa bila hivyo.',
'Shopify_G_Currently' => 'Kwa sasa: ghala {warehouse}, eneo {location}',
'Shopify_G_Not_Set_Lower' => 'haijawekwa',
'Shopify_G_Ready' => 'tayari',
'Shopify_G_Incomplete' => 'haijakamilika',
'Shopify_G_Manual_Syncs' => 'Usawazishaji unaoanzisha kwa mkono',
'Shopify_G_Manual_Desc' => 'Usawazishaji ulioanzishwa kutoka {centre} hujibu mara moja na kuendeshwa chinichini, kwa vipande vifupi ambavyo kila kimoja huendelea pale kilichotangulia kilipoishia. Orodha kubwa ya bidhaa haikatizwi katikati kamwe na huduma za hosting zinazokatisha maombi marefu ya wavuti (LiteSpeed, nginx, load balancer), na kufunga ukurasa hakuusimamishi. Mfanyakazi (worker) wa hilo ni mstari mmoja zaidi wa cron:',
'Shopify_G_Cron_Copied' => 'Mstari wa cron umenakiliwa',
'Shopify_G_Manual_Note' => 'Bila huo usawazishaji bado hukamilika, lakini tu wakati ukurasa wa Sync Centre unabaki wazi: hakuna worker anayechukua uendeshaji ndani ya sekunde chache, ukurasa wenyewe huuendeleza, ombi moja fupi kwa wakati. Kwenye Windows tumia Task Scheduler kila dakika: programu {program}, hoja {args}, ikianzia katika {dir}.',
'Shopify_G_Then_Pick' => 'Kisha chagua jinsi linavyobaki likiendana',
'Shopify_G_Right_Away' => 'Papo hapo',
'Shopify_G_Stock_Live' => 'stoku hai',
'Shopify_G_Stock_Not_Live' => 'stoku si hai',
'Shopify_G_Realtime_Lead' => 'Kila badiliko hutumwa linapotokea, ndani ya sekunde. Nusu mbili, na ni swichi tofauti: {webhooks} huleta matukio ya duka ndani, na {push} hutuma stoku nje.',
'Shopify_G_Webhooks_Lower' => 'Webhook',
'Shopify_G_Instant_Push_Lower' => 'usukumaji wa stoku papo hapo',
'Shopify_G_Webhooks_In' => 'Webhook — duka → ERP',
'Shopify_G_Webhooks_Desc' => 'Oda, mabadiliko ya hali ya oda, na uhariri wa bidhaa, wateja na stoku uliofanywa kwenye Shopify. Fungua duka na ubonyeze {button} kwenye {tab} yake — ni salama kubonyeza mara mbili. Shopify hutuma kwa:',
'Shopify_G_Webhooks_Tab' => 'kichupo cha Webhook',
'Shopify_G_Webhooks_Note' => 'Anwani lazima ifikike kutoka intaneti kupitia HTTPS — Shopify haitawasilisha kwa {localhost} au kikoa cha {test}. Kila uwasilishaji hurekodiwa mara moja, hivyo majaribio ya marudio ya Shopify hayawezi kuunda oda maradufu, na uliyoshindwa unaweza kuendeshwa upya. Uwasilishaji hukataliwa hadi siri ya kusaini kutoka hatua ya 1 ihifadhiwe.',
'Shopify_G_Instant_Out' => 'Usukumaji wa stoku papo hapo — ERP → duka',
'Shopify_G_Setting_Missed' => 'Huu ndio mpangilio ambao watu huusahau',
'Shopify_G_Pos_Not_Auto' => 'Uuzaji wa POS {not} haufiki Shopify wenyewe. Ukiachwa umezimwa, duka hugundua tu kwenye hatua inayofuata ya usukumaji wa Stoku — na katika kipindi hicho linaweza kuuza kipande ambacho tayari umekiuza kwenye kasha la fedha.',
'Shopify_G_Not' => 'kamwe',
'Shopify_G_Tick_Push' => 'Weka alama kwenye {setting} katika {where}. Huo ndio usanidi wote — hakuna worker, hakuna cron. Kila uuzaji, marejesho na marekebisho kisha hutuma usukumaji wa bidhaa hizo pekee, mara tu baada ya uuzaji kuhifadhiwa, na uuzaji wa mistari ishirini hugharimu usukumaji mmoja, si ishirini. Kasha la fedha halisubiri kamwe.',
'Shopify_G_This_Store' => 'Duka hili:',
'Shopify_G_Push_On' => 'imewashwa — stoku husukumwa inapobadilika',
'Shopify_G_Push_Off' => 'imezimwa — stoku kwa ratiba pekee',
'Shopify_G_Push_Note' => 'Bidhaa ambazo tayari zina uoanishaji wa Shopify pekee, na mienendo katika ghala la duka hili pekee, ndizo husukumwa. Shughuli za jumla — kufuta bidhaa, kuweka upya ghala — huandika stoku bila kuchochea tukio, ambayo ni sababu mojawapo ya kubakiza pia hatua ya stoku iliyopangwa.',
'Shopify_G_Nothing_Install' => 'Hakuna kingine cha kusakinisha',
'Shopify_G_No_Worker_Note' => 'Hakuna nusu yoyote inayohitaji queue worker au ingizo la cron. Webhook inayoingia hushughulikiwa ndani ya ombi ambalo Shopify hufanya; usukumaji wa stoku unaotoka huendeshwa katika mchakato ule ule uliohudumia uuzaji, {after} jibu kurudishwa — hivyo kasha la fedha halisubiri Shopify kamwe, na duka linaloacha kujibu huachwa baada ya sekunde kumi na kusubiri usukumaji wa stoku unaofuata wa ratiba.',
'Shopify_G_After' => 'baada ya',
'Shopify_G_Artisan_Note' => 'Isipokuwa moja: badiliko la stoku lililofanywa na amri ya artisan halina jibu la kusubiri, hivyo huwekwa kwenye foleni ya {queue} badala yake. Ukitaka hayo nayo yatoke haraka, endesha foleni hiyo:',
'Shopify_G_On_Schedule' => 'Kwa ratiba',
'Shopify_G_On_Lower' => 'imewashwa',
'Shopify_G_Off_Lower' => 'imezimwa',
'Shopify_G_Scheduled_Lead' => 'Kila kitu hukaguliwa upya mara kwa mara, pande zote mbili. Ni polepole kuliko wakati halisi, lakini ndicho kinachosukuma stoku nje kwa maduka yasiyotumia usukumaji wa papo hapo, kinachonasa Webhook iliyokosekana, na njia pekee ya kusogeza orodha nzima ya bidhaa.',
'Shopify_G_Cron_Entry' => 'Ingizo la cron',
'Shopify_G_Cron_Entry_Desc' => 'Hakuna kilichopangwa kinachoendeshwa bila hilo. Mstari mmoja, kwa moduli hii pekee — uongeze kando ya chochote kingine ulichochagua kupanga:',
'Shopify_G_Cron_Note' => 'Kila dakika tano ndiyo kipimo kidogo zaidi ambacho mpango unaweza kutumia, kwa sababu dakika tano ndicho kipindi kifupi zaidi cha hatua. Ingizo lenye kipindi kikubwa zaidi huwa tu kiwango cha chini — kwa {example}, hatua iliyowekwa dakika 5 huendeshwa kila dakika 15. Kwenye Windows tumia Task Scheduler: programu {program}, hoja {args}, ikianzia katika {dir}.',
'Shopify_G_Switch_On_Plan' => 'Iwashe, na uchague mpango',
'Shopify_G_Plan_Desc' => '{where} Swichi huamua kama cron inaweza kutenda kabisa; mpango huamua inachofanya. {step} ni kipengele kimoja kwa mwelekeo mmoja chenye kipindi chake — {first}, {second}. Kipindi chaguomsingi hutumiwa na hatua yoyote inayoacha kisanduku chake wazi.',
'Shopify_G_Step_Lower' => 'hatua',
'Shopify_G_Plan_Note' => 'Acha mpango wazi na duka litavuta oda na kusukuma stoku kwa kipindi chaguomsingi, ambacho ndicho maduka mengi hutaka. Oda ni za kuvuta pekee: Shopify ndipo mteja huweka oda.',
'Shopify_G_Schedule_On' => 'ratiba imewashwa',
'Shopify_G_Schedule_Off' => 'ratiba imezimwa — kwa mkono pekee',
'Shopify_G_When_Step_Runs' => 'Lini hatua huendeshwa kweli',
'Shopify_G_When_Note' => 'Hatua inastahili kuendeshwa wakati hatua hiyo hiyo mara ya mwisho {started} zamani kuliko kipindi chake, kama inavyosomwa kutoka historia ya uendeshaji. Hivyo usawazishaji unaoanzisha kwa mkono huahirisha unaofuata wa kiotomatiki, na hatua inayoendelea kushindwa hujaribiwa tena kwa kipindi chake badala ya kila mzunguko. Muhtasari wa duka huonyesha uendeshaji wa mwisho wa kila hatua, muda unaofuata wa kustahili, na sababu ya kuzuiwa inapozuiwa. Endesha usukumaji wa kwanza wa orodha ya bidhaa kwa mkono — ukitumia {dryRun} kwanza — kabla ya kuuweka kwenye ratiba.',
'Shopify_G_Started_Lower' => 'ilianza',
'Shopify_G_Where_Setting' => 'Mahali kila mpangilio ulipo',
'Shopify_G_Where_Setting_Note' => 'Yote haya yako kwenye duka lililopo: {path}, kisha penseli (au {edit} kwenye ukurasa wa duka lenyewe).',
'Shopify_G_Product_Images' => 'Picha za bidhaa',
'Shopify_G_Img_1' => 'Picha hutumwa pamoja na bidhaa wakati wa {push} — picha kuu kwanza, kisha matunzio, kisha moja kwa kila toleo lenye picha yake, hadi hamsini.',
'Shopify_G_Products_Push' => 'usukumaji wa bidhaa',
'Shopify_G_Img_2' => 'Picha ya toleo hupakiwa pamoja na bidhaa kisha {assigned}, ambayo ndiyo jinsi Shopify inavyoipanga: toleo huelekeza kwenye moja ya picha za bidhaa. Toleo linalotumia tena picha kuu halipakii mara mbili.',
'Shopify_G_Assigned' => 'hupewa toleo hilo',
'Shopify_G_Img_3' => 'Picha iliyohifadhiwa kama faili {uploaded} kwa Shopify, haiunganishwi kwa kiungo, hivyo inafanya kazi hata kama usakinishaji huu haufikiki kutoka intaneti. Picha iliyoongezwa kama kiungo kilichobandikwa hupewa Shopify kama URL hiyo, ambayo lazima ifikike hadharani.',
'Shopify_G_Uploaded' => 'hupakiwa',
'Shopify_G_Img_4' => 'Hutumwa tena tu zinapobadilika kweli — usukumaji unaobadilisha bei tu huacha picha za duka bila kuguswa, kwa sababu kuzituma hubadilisha seti nzima.',
'Shopify_G_Img_5' => 'Kuondoa picha kwenye ERP {not} hakuifuti kwenye Shopify. Ifute huko pia, la sivyo duka litaendelea kuionyesha.',
'Shopify_G_Commands' => 'Amri zinazofaa kujua',
'Shopify_G_Command_Copied' => 'Amri imenakiliwa',
'Shopify_G_Foot' => 'Kila usawazishaji huandika kwenye {logs}, na Muhtasari wa kila duka huonyesha lini kila hatua iliendeshwa mwisho, lini inastahili tena, na kinachoizuia inapozuiwa. Hapo ndipo pa kuangalia kwanza usawazishaji usipofanya ulichotarajia.',
'Shopify_G_Covers' => 'Hushughulikia',
'Shopify_G_Covers_Rt' => 'Oda na uhariri uliofanywa kwenye Shopify; stoku inayotoka ERP (uuzaji wa POS, marejesho, marekebisho)',
'Shopify_G_Covers_Sch' => 'Kila kitu, pande zote mbili — ikiwemo usukumaji wa orodha ya bidhaa na chochote ambacho njia ya haraka ilikosa',
'Shopify_G_Speed' => 'Kasi',
'Shopify_G_Speed_Rt' => 'Sekunde',
