'StoreAdm_PG_Paystack_Webhook_Url' => 'URL ya Webhook (kinga ya ziada isiyo ya lazima — iweke chini ya Settings → API Keys & Webhooks kwenye dashibodi ya Paystack; maombi huthibitishwa kwa HMAC kwa ufunguo wako wa siri):',
