'StoreAdm_PG_Flutterwave_Info' => 'Hutumia Flutterwave v3 API kwa funguo za kawaida. Majaribio au halisi huamuliwa na jozi ya funguo ({keys} dhidi ya funguo halisi) — hakuna swichi tofauti ya sandbox. Sarafu ya duka lazima iwe imewezeshwa kwenye akaunti yako ya Flutterwave.',
