'StoreAdm_PG_Razorpay_Info' => 'Hutumia Razorpay Payment Links (kadi, UPI, benki ya mtandaoni, pochi). Majaribio au halisi huamuliwa na jozi ya funguo ({keys}) — hakuna swichi tofauti ya sandbox.',
