'Cr_Guide_Your_Setup_Help' => 'Hali ya usanidi wako. Kila hatua inaunganisha kwenye ukurasa unaoifanya.',
'Cr_Guide_Optional' => 'Si lazima',
'Cr_Guide_Step_Account' => 'Ongeza akaunti ya msafirishaji',
'Cr_Guide_Step_Account_Help' => 'Chagua msafirishaji wako na ubandike funguo za API kutoka kwenye dashibodi yake. Akaunti kadhaa zinaruhusiwa, kwa mfano moja kwa kila ghala.',
'Cr_Guide_Step_Test' => 'Jaribu muunganisho',
'Cr_Guide_Step_Test_Help' => 'Kujaribu muunganisho hukagua funguo na mara nyingi huorodhesha misimbo ambayo chaguo za msafirishaji zinahitaji.',
'Cr_Guide_Step_Webhook' => 'Sajili URL ya Webhook',
'Cr_Guide_Step_Webhook_Help' => 'Wasafirishaji wanaotuma masasisho wenyewe wanahitaji URL ya Webhook ya akaunti (imeorodheshwa hapa chini) ili hali zibadilike papo hapo. Wengine hukaguliwa kwa ratiba.',
'Cr_Guide_Step_Cod' => 'Chagua mahali malipo ya COD yanapokwenda',
'Cr_Guide_Step_Cod_Help' => 'Katika Mipangilio ya Msafirishaji, chagua akaunti ambamo malipo ya COD yanarekodiwa, na jinsi vifurushi vilivyorejeshwa na ada za msafirishaji zinavyoshughulikiwa.',
'Cr_Guide_Step_Notify' => 'Waarifu wateja wako',
'Cr_Guide_Step_Notify_Help' => 'SMS, Email au WhatsApp katika hali utakazochagua, pamoja na kiungo cha ukurasa wa ufuatiliaji.',
'Cr_Guide_Step_Book' => 'Weka oda yako ya kwanza kwa msafirishaji',
'Cr_Guide_Step_Book_Help' => 'Kwenye orodha ya mauzo, fungua menyu ya uuzaji na uchague Tuma kwa msafirishaji, au weka alama kwenye mauzo kadhaa na uyatume kwa pamoja.',
'Cr_Guide_Step_Errors' => 'Fuatilia hitilafu',
'Cr_Guide_Step_Errors_Help' => 'Hakuna hitilafu za msafirishaji katika saa 24 zilizopita.',
'Cr_Guide_Courier_Setup' => 'Usanidi wa msafirishaji',
'Cr_Guide_Pick_Courier' => 'Chagua msafirishaji ili kuona anachohitaji',
'Cr_Guide_Add_This' => 'Ongeza msafirishaji huyu',
'Cr_Guide_You_Need' => 'Unahitaji',
'Cr_Guide_No_Keys' => 'Hakuna funguo za API: hakuna cha kuunganisha.',
'Cr_Guide_Good_To_Know' => 'Vizuri kujua',
'Cr_Guide_Webhooks' => 'Anwani za Webhook',
'Cr_Guide_How' => 'Jinsi ya kuisajili',
'Cr_Guide_How_It_Works' => 'Jinsi inavyofanya kazi',
'Cr_Guide_Meaning' => 'Maana',
'Cr_Guide_T_Statuses' => 'Hali',
'Cr_Guide_Statuses_Note' => 'Hali husonga mbele tu, kwa hivyo sasisho lililochelewa haliwezi kurudisha kifurushi nyuma. Kifurushi kilichowasilishwa bado kinaweza kuripotiwa kuwa kinarejeshwa au kimerejeshwa.',
'Cr_Guide_S_booked' => 'Msafirishaji ana oda; hakuna aliyeikusanya bado. Uhifadhi unaweza kughairiwa sasa tu.',
'Cr_Guide_S_picked_up' => 'Msafirishaji amekusanya kifurushi.',
'Cr_Guide_S_in_transit' => 'Kinasafirishwa kati ya vituo, kiko forodhani au kimezuiliwa.',
'Cr_Guide_S_out_for_delivery' => 'Kiko na mpeleka mizigo leo.',
'Cr_Guide_S_failed_attempt' => 'Hakuwepo nyumbani, amekataa au anwani si sahihi. Msafirishaji atajaribu tena au atakirejesha.',
'Cr_Guide_S_delivered' => 'Kimekabidhiwa kwa mteja. Kiasi cha COD kinakuwa kimekusanywa na msafirishaji.',
'Cr_Guide_S_returning' => 'Kiko njiani kurudi kwako.',
'Cr_Guide_S_returned' => 'Kimerudi kwako: kinasubiri katika Marejesho ya kukagua, au kinarudishwa kwenye stoku kiotomatiki.',
'Cr_Guide_S_cancelled' => 'Uhifadhi ulighairiwa.',
'Cr_Guide_T_Booking' => 'Kuweka oda kwa msafirishaji',
'Cr_Guide_B_Booking' => 'Tuma kwa msafirishaji hujaza fomu kutoka kwenye uuzaji: mpokeaji, anwani, kiasi ambacho bado ni deni kama COD, na uzito wa bidhaa. Wasafirishaji wenye orodha zao za miji huonyesha kichaguzi, na chaguo lako hukumbukwa kwa mji huo. Wakusanyaji (aggregators), DHL, FedEx, UPS na Lalamove hutoa Linganisha bei: chagua bei na Weka oda huinunua. Mauzo kadhaa yanaweza kuwekwa kwa pamoja kutoka kwenye orodha ya mauzo.',
'Cr_Guide_T_Cod' => 'Malipo wakati wa kupokea (COD)',
'Cr_Guide_B_Cod' => 'Kifurushi cha COD hutoka Hakijakusanywa kwenda Kimekusanywa na msafirishaji (wakati wa kuwasilisha) hadi Kimelipwa kwako. Wasafirishaji wanaoripoti malipo husogeza hatua ya mwisho wenyewe; kwa wengine tumia Sasisha COD. Akaunti ikiwa imechaguliwa katika Mipangilio ya Msafirishaji, malipo hurekodiwa kama malipo kwenye uuzaji. Ada za msafirishaji zinaweza kuhifadhiwa kama gharama mara kifurushi kinapokamilika.',
'Cr_Guide_T_Returns' => 'Vifurushi vilivyorejeshwa',
'Cr_Guide_B_Returns' => 'Kwa chaguo-msingi kifurushi kilichorejeshwa husubiri katika Usafirishaji wa Msafirishaji chini ya Marejesho ya kukagua. Rudisha kwenye stoku huunda marejesho ya uuzaji kwa oda nzima na kurudisha bidhaa kwenye stoku; Puuza hairudishi chochote, kwa vifurushi vilivyoharibika au vilivyopotea. Mipangilio ya Msafirishaji inaweza badala yake kurudisha kwenye stoku kiotomatiki.',
'Cr_Guide_T_Customers' => 'Ujumbe kwa wateja na ukurasa wa ufuatiliaji',
'Cr_Guide_B_Customers' => 'Arifa kwa wateja katika Mipangilio ya Msafirishaji hutuma SMS, Email au WhatsApp katika hali utakazoweka alama, kila moja mara moja kwa kila kifurushi, kwa maandishi yako mwenyewe. Ukurasa wa ufuatiliaji katika duka lako la mtandaoni huwaruhusu wateja kufuatilia kifurushi kwa namba ya ufuatiliaji, au kwa namba ya oda na simu. Wateja wanaorejesha vifurushi mara kwa mara hupata beji ya hatari ya marejesho unapoweka oda.',
'Cr_Guide_T_Labels' => 'Lebo',
'Cr_Guide_B_Labels' => 'Chapisha lebo hutoa lebo ya msafirishaji mwenyewe anapoitoa (PDF, kiungo au picha), vinginevyo lebo ya Stocky yenye msimbopau wa ufuatiliaji na kiasi cha kukusanya. Ruhusu madirisha ibukizi (pop-ups) kwa tovuti hii ili kuchapisha. DHL, FedEx na UPS hutoa lebo yao mara moja tu, wakati wa kuweka oda, na Stocky huihifadhi kwa ajili ya kuchapisha tena.',
'Cr_Guide_T_Faq' => 'Utatuzi wa matatizo',
'Cr_Guide_Q_Test' => 'Kujaribu muunganisho kunashindikana',
'Cr_Guide_A_Test' => 'Funguo za hali ya majaribio huenda na Hali ya majaribio na funguo halisi huenda na Halisi; ni tofauti. Fungua Kumbukumbu za msafirishaji na usome jibu la msafirishaji kwa sababu kamili.',
'Cr_Guide_Q_City' => 'Msafirishaji anakataa mji au anwani',
'Cr_Guide_A_City' => 'Chagua mji kutoka kwenye orodha ya miji ya msafirishaji katika fomu ya kuweka oda; wasafirishaji hukubali majina yao wenyewe tu. Wasafirishaji wanaofanya kazi na anwani za posta pia wanahitaji mkoa/jimbo, msimbo wa posta na nchi kwa herufi mbili.',
'Cr_Guide_Q_Webhook' => 'Hali hazibadiliki zenyewe',
'Cr_Guide_A_Webhook' => 'Kwa wasafirishaji wanaotuma masasisho, hakikisha URL ya Webhook imesajiliwa kwa msafirishaji: Kumbukumbu za msafirishaji huonyesha kila sasisho lililopokelewa, au sababu ya kukataliwa (kwa mfano siri isiyo sahihi). Wasafirishaji wengine hukaguliwa kwa ratiba iliyo katika Mipangilio ya Msafirishaji, na Kagua hali sasa huuliza papo hapo.',
'Cr_Guide_Q_Stuck' => 'Usafirishaji unaonyesha hitilafu ya ukaguzi wa hali',
'Cr_Guide_A_Stuck' => 'Msafirishaji alikataa ukaguzi wa mwisho; sababu iko kwenye usafirishaji na katika Kumbukumbu za msafirishaji. Baada ya kushindwa mara kwa mara usafirishaji haukaguliwi tena kiotomatiki: rekebisha chanzo, kisha tumia Kagua hali sasa.',
'Cr_Guide_Q_Label' => 'Hakuna kinachofunguka wakati wa kuchapisha lebo',
'Cr_Guide_A_Label' => 'Kivinjari chako kimezuia dirisha ibukizi. Ruhusu madirisha ibukizi (pop-ups) kwa tovuti hii na ujaribu tena.',
'Cr_Guide_Q_Cod' => 'Malipo ya COD hayakurekodiwa kwenye uuzaji',
'Cr_Guide_A_Cod' => 'Katika Mipangilio ya Msafirishaji, malipo wakati wa kupokea yanahitaji swichi iwashwe na akaunti ichaguliwe. Bila akaunti, malipo huwekwa alama tu kuwa yamelipwa.',
