'Tfa_Reset' => 'Weka upya hatua mbili',
'Tfa_Reset_Title' => 'Weka upya uthibitishaji wa hatua mbili?',
'Tfa_Reset_Help' => ':name ataingia kwa nenosiri lake pekee na kisha anaweza kusanidi programu yake ya uthibitishaji tena. Fanya hivi tu baada ya kuthibitisha ni nani anayeomba.',
'Tfa_Guide_Lead' => 'Uthibitishaji wa hatua mbili (2FA) huongeza hatua ya pili wakati wa kuingia: baada ya nenosiri, wafanyakazi huandika msimbo wa tarakimu 6 kutoka kwenye programu ya uthibitishaji kwenye simu zao. Nenosiri lililoibwa au lililokisiwa halitoshi tena kuingia.',
'Tfa_Guide_State_Required' => 'Unahitajika',
'Tfa_Guide_State_Optional' => 'Hapana — si lazima kwa kila mtu',
'Tfa_Guide_State_Trust' => 'Vifaa vinavyoaminika',
'Tfa_Guide_State_Users' => 'Watumiaji walio na 2FA imewashwa',
'Tfa_Guide_Staff_Title' => 'Kwa kila mfanyakazi',
'Tfa_Guide_App_Title' => 'Sakinisha programu ya uthibitishaji',
'Tfa_Guide_App_Text' => 'Programu yoyote inayotumia misimbo ya kawaida ya tarakimu 6 (TOTP) inafanya kazi. Ni za bure na zinafanya kazi bila mtandao:',
'Tfa_Guide_Enable_Title' => 'Uwashe kutoka kwenye wasifu',
'Tfa_Guide_Enable_1' => 'Fungua Wasifu (menyu ya picha ya wasifu juu kulia) na utafute kadi ya "Uthibitishaji wa hatua mbili".',
'Tfa_Guide_Enable_2' => 'Bofya "Washa" na uthibitishe kwa nenosiri la sasa.',
'Tfa_Guide_Enable_3' => 'Skani msimbo wa QR kwa programu, au andika ufunguo unaoonyeshwa chini yake.',
'Tfa_Guide_Enable_4' => 'Weka msimbo wa tarakimu 6 unaoonyeshwa na programu ili kumaliza.',
'Tfa_Guide_Open_Profile' => 'Fungua wasifu wangu',
'Tfa_Guide_Codes_Title' => 'Hifadhi misimbo ya urejeshaji',
'Tfa_Guide_Codes_Text' => 'Mara tu baada ya usanidi, misimbo 8 ya urejeshaji huonyeshwa mara moja. Kila mmoja huchukua nafasi ya msimbo wa simu mara moja tu — kwa simu iliyopotea, iliyoharibika au iliyowekwa upya. Ipakue au uinakili na uihifadhi mahali salama, mbali na simu.',
'Tfa_Guide_Codes_Note' => 'Inakaribia kuisha? "Misimbo mipya ya urejeshaji" kwenye wasifu hubadilisha seti nzima; ile ya zamani huacha kufanya kazi.',
'Tfa_Guide_Signin_Title' => 'Kuingia',
'Tfa_Guide_Signin_Text' => 'Baada ya Email na nenosiri, ukurasa wa kuingia huomba msimbo wa sasa kutoka kwenye programu. Misimbo hubadilika kila sekunde 30 na kila mmoja hufanya kazi mara moja.',
'Tfa_Guide_Signin_Trust' => 'Kuweka alama kwenye "Usiulize tena kwenye kifaa hiki" huruka msimbo kwenye kivinjari hicho kwa siku :days.',
'Tfa_Guide_Signin_Recovery' => 'Huna simu karibu? Bofya "Tumia msimbo wa urejeshaji" na uandike mmoja wa misimbo iliyohifadhiwa.',
'Tfa_Guide_Admin_Title' => 'Kwa wasimamizi',
'Tfa_Guide_Require_Title' => 'Ufanye kuwa wa lazima',
'Tfa_Guide_Require_Text' => 'Washa "Lazimisha uthibitishaji wa hatua mbili" kwenye kadi hii, kisha uchague majukumu ambayo lazima yautumie — au acha orodha wazi kwa kila mtumiaji. Bofya Wasilisha ili kuhifadhi.',
'Tfa_Guide_Require_Next' => 'Hakuna anayetolewa nje. Watumiaji ambao bado hawana 2FA wataongozwa kuusanidi kwenye ukurasa wa kuingia wakati wa kuingia kwao kunakofuata, kabla ya kuingia, na wataona misimbo yao ya urejeshaji hapo.',
'Tfa_Guide_Require_Note' => 'Watumiaji ambao unalazimishwa kwao hawawezi kuuzima kutoka kwenye wasifu wao.',
'Tfa_Guide_Trust_Title' => 'Vifaa vinavyoaminika',
'Tfa_Guide_Trust_Text' => '"Kumbuka vifaa vinavyoaminika" huweka muda ambao kivinjari kinaweza kuruka msimbo baada ya kuingia kwa mafanikio. Chagua "Uliza msimbo kila wakati" kwa kompyuta za pamoja au za umma kama vile POS ya dukani.',
'Tfa_Guide_Trust_Note' => 'Kupunguza idadi hufupisha muda wa vifaa vinavyoaminika tayari; kuzima 2FA au kuiweka upya huvisahau vyote.',
'Tfa_Guide_Lost_Title' => 'Simu imepotea na hakuna misimbo ya urejeshaji',
'Tfa_Guide_Lost_Text' => 'Kwenye ukurasa wa Watumiaji, watumiaji walio na 2FA huonyesha "Imewashwa" katika safu ya 2FA. Kitufe cha ngao katika Vitendo huiweka upya: mtumiaji huingia kwa nenosiri pekee na kusanidi programu tena (au huombwa kufanya hivyo, ikiwa unalazimishwa).',
'Tfa_Guide_Lost_Warn' => 'Thibitisha ni nani anayeomba kabla ya kuweka upya — kuweka upya huondoa ulinzi ambao 2FA huipa akaunti hiyo.',
'Tfa_Guide_Open_Users' => 'Fungua Watumiaji',
'Tfa_Guide_Mobile_Title' => 'Programu ya simu na API',
'Tfa_Guide_Mobile_Text' => 'Programu ya simu na sehemu ya tokeni ya API huomba msimbo uleule. Ikiwa 2FA inalazimishwa kwa mtumiaji ambaye bado hajausanidi, lazima aingie kwenye wavuti mara moja ili kufanya hivyo.',
'Tfa_Guide_Protect_Title' => 'Ulinzi uliojengwa ndani',
'Tfa_Guide_Protect_1' => 'Misimbo 5 isiyo sahihi huzuia uwekaji wa msimbo kwa mtumiaji huyo kwa dakika 15, bila kujali mipangilio ya kufungiwa iliyo hapo juu.',
'Tfa_Guide_Protect_2' => 'Kila msimbo na kila msimbo wa urejeshaji hufanya kazi mara moja tu.',
'Tfa_Guide_Protect_3' => '"Rekodi shughuli za kuingia" ikiwa imewashwa, misimbo isiyo sahihi huonekana kwenye orodha ya Shughuli za kuingia kama "Msimbo wa 2FA si sahihi".',
'Tfa_Guide_Trouble_Title' => 'Utatuzi wa matatizo',
'Tfa_Guide_Faq_Clock_Q' => '“Msimbo huo si sahihi” kwa msimbo mpya',
'Tfa_Guide_Faq_Clock_A' => 'Huenda saa ya simu si sahihi. Misimbo inategemea muda: weka tarehe na saa ya simu kuwa za kiotomatiki (muda wa mtandao), kisha jaribu msimbo unaofuata.',
'Tfa_Guide_Faq_Phone_Q' => 'Kuhamia simu mpya',
'Tfa_Guide_Faq_Phone_A' => 'Tumia kipengele cha uhamisho cha programu ya uthibitishaji yenyewe, au zima 2FA kwenye wasifu na uiwashe tena kwa simu mpya (ikiwa inalazimishwa, muombe msimamizi aiweke upya badala yake).',
'Tfa_Guide_Faq_Locked_Q' => '“Misimbo mingi mno isiyo sahihi”',
'Tfa_Guide_Faq_Locked_A' => 'Subiri muda unaoonyeshwa (hadi dakika 15), au mwombe msimamizi aweke upya 2FA ya mtumiaji.',
'Tfa_Guide_Faq_Key_Q' => 'Hakuna mwenye 2FA anayeweza kuingia baada ya kuhamisha seva',
'Tfa_Guide_Faq_Key_A' => 'Siri za 2FA zimesimbwa kwa APP_KEY iliyo kwenye faili la .env. Tumia APP_KEY ileile unapohamisha au kurejesha programu; ikiwa ilibadilika, msimamizi asiye na 2FA lazima aweke upya watumiaji walioathirika.',
'Tfa_Guide_Button' => 'Mwongozo',
'Tfa_Guide_Title' => 'Mwongozo wa uthibitishaji wa hatua mbili',
'Sec_2fa_Pending' => ':count bado hawajausanidi',
'Sec_2fa_See_Who' => 'Ona ni nani',
'Sec_2fa_Grace_Off' => 'Hakuna — sanidi wakati wa kuingia kunakofuata',
