'Tfa_Guide_Rollout_Title' => 'Usambaze kwa kila mtumiaji',
'Tfa_Guide_Rollout_1' => 'Uwashe kwa akaunti yako mwenyewe kwanza (Wasifu), ili ujue hatua.',
'Tfa_Guide_Rollout_2' => 'Iambie timu yako programu ya kusakinisha na kwamba usanidi huchukua dakika moja wakati wa kuingia.',
'Tfa_Guide_Rollout_3' => 'Washa "Lazimisha uthibitishaji wa hatua mbili", acha "Unahitajika kwa" wazi (= kila mtumiaji), na kwa hiari chagua muda wa neema. Bofya Wasilisha.',
'Tfa_Guide_Rollout_4' => 'Bofya "Toa nje watumiaji wasio na 2FA" ili watu ambao tayari wameingia wausanidi sasa badala ya wakati fulani baadaye wa kuingia. Wewe unabaki ndani.',
'Tfa_Guide_Rollout_5' => 'Fuatilia maendeleo kwa kihesabu kilicho kwenye kadi hii, au kichujio cha "Inahitaji usanidi" kwenye ukurasa wa Watumiaji.',
'Tfa_Guide_Rollout_Note' => 'Ukiwa na muda wa neema, skrini ya usanidi huonyesha “Nikumbushe baadaye” hadi tarehe ya mwisho; baada ya hapo, usanidi unahitajika ili kuingia.',
'Tfa_Guide_Customers_Title' => 'Akaunti za wateja (duka na lango la mteja)',
'Tfa_Guide_Customers_Text' => 'Wateja wanaweza pia kulinda akaunti zao wenyewe. Si lazima kwa kila mteja na hailazimishwi kamwe: iwashe chini ya Mipangilio ya Duka → Udhibiti wa Ufikiaji wa Usajili (duka la mtandaoni) na Lango la Mteja → Mipangilio ya Lango (lango la mteja).',
'Tfa_Guide_Customers_1' => 'Wateja huiwasha kutoka Akaunti Yangu (duka) au Wasifu (lango).',
'Tfa_Guide_Customers_2' => 'Wanachagua msimbo unaotumwa kwa Email — rahisi zaidi, hakuna programu inayohitajika — au programu ya uthibitishaji yenye misimbo ya urejeshaji.',
'Tfa_Guide_Customers_3' => 'Misimbo inayotumwa kwa Email inahitaji mipangilio ya barua inayofanya kazi (Mipangilio → Mipangilio ya Barua). Muda wake huisha baada ya dakika 10.',
'Tfa_Guide_Customers_4' => 'Kuzima chaguo hili baadaye huzuia usanidi mpya; wateja ambao tayari wanaitumia wataendelea kuulizwa na wanaweza kuizima wenyewe.',
'Tfa_Required_Grace_Notice' => 'Msimamizi wako analazimisha uthibitishaji wa hatua mbili. Unaweza kuuahirisha wakati wa kuingia hadi :date; baada ya hapo, usanidi unahitajika.',
